// ===== Контекст + «случайные ингредиенты» для идеи рилса =====
const TZ = 'Asia/Yekaterinburg';                       // Октябрьский (РБ)
const now = new Date();
const wd = now.toLocaleDateString('ru-RU', { weekday: 'long', timeZone: TZ });
const dateStr = now.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric', timeZone: TZ });
const hour = parseInt(now.toLocaleTimeString('ru-RU', { hour: '2-digit', hour12: false, timeZone: TZ }));
const part = hour < 6 ? 'глубокая ночь' : hour < 12 ? 'утро' : hour < 18 ? 'день' : 'вечер';
const month = parseInt(now.toLocaleDateString('en-US', { month: 'numeric', timeZone: TZ }));
const season = [12,1,2].includes(month) ? 'зима, мороз, тёмные вечера' : [3,4,5].includes(month) ? 'весна, слякоть' : [6,7,8].includes(month) ? 'лето, жара' : 'осень, дожди, темнеет рано';

// ближайшие поводы (в пределах 16 дней)
const y = parseInt(now.toLocaleDateString('en-US', { year: 'numeric', timeZone: TZ }));
const nthWeekday = (year, m, wdIdx, n) => { let c = 0; for (let d = 1; d <= 31; d++) { const dt = new Date(Date.UTC(year, m, d)); if (dt.getUTCMonth() !== m) break; if (dt.getUTCDay() === wdIdx && ++c === n) return dt; } };
const lastSunday = (year, m) => { for (let d = 31; d >= 1; d--) { const dt = new Date(Date.UTC(year, m, d)); if (dt.getUTCMonth() === m && dt.getUTCDay() === 0) return dt; } };
const events = [];
for (const yy of [y, y + 1]) events.push(
  ['Новый год', new Date(Date.UTC(yy, 11, 31))], ['Старт зимней сессии у студентов', new Date(Date.UTC(yy, 0, 12))],
  ['Татьянин день (День студента)', new Date(Date.UTC(yy, 0, 25))], ['День защитника Отечества 23 февраля', new Date(Date.UTC(yy, 1, 23))],
  ['8 Марта', new Date(Date.UTC(yy, 2, 8))], ['1 сентября', new Date(Date.UTC(yy, 8, 1))], ['Хэллоуин', new Date(Date.UTC(yy, 9, 31))],
  ['Чёрная пятница', nthWeekday(yy, 10, 5, 4)], ['День матери', lastSunday(yy, 10)], ['Начало зимы', new Date(Date.UTC(yy, 11, 1))],
  ['Начало каникул', new Date(Date.UTC(yy, 11, 28))]);
const today0 = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const near = events.filter(([, d]) => d && (d.getTime() - today0) / 86400000 >= -1 && (d.getTime() - today0) / 86400000 <= 16)
  .map(([n, d]) => `${n} (через ${Math.max(0, Math.round((d.getTime() - today0) / 86400000))} дн.)`);

const pick = a => a[Math.floor(Math.random() * a.length)];
const pickN = (a, n) => { const c = [...a], r = []; while (r.length < n && c.length) r.push(c.splice(Math.floor(Math.random() * c.length), 1)[0]); return r; };

const FORMATS = [
  'POV: «ты — …» (съёмка от первого лица)', '«Ожидание vs реальность»', 'Мини-сценка с неожиданной развязкой в последней секунде',
  'Быстрый челлендж с таймером на экране', '«Угадай по звуку» (клик мышки, крик, кулер, энергетик)', 'Тренд-формат «до / после»',
  'Реакция администратора на дикую просьбу гостя', 'ASMR клуба (клики, подсветка, баночка энергетика)', 'Секретный «уровень» клуба — квест для гостей',
  'Дуэль «админ против гостя» на скорость/меткость', 'Фейковый «документальный фильм» о клубе с пафосным закадровым голосом',
  'Переход-«телепорт» из реальности в игру', '«Типы гостей клуба» (узнаваемые персонажи)', 'Один дубль без склеек, обязательно удачная концовка',
  'Лайфхак для геймеров (быстро и полезно)', 'Слоу-мо «клатч» с эпичной подачей', 'Ответ на «комментарий подписчика» (идею можно взять из типичных вопросов)'];
const HEROES = ['администратор в одиночку', 'два администратора', 'гость-новичок, который впервые в клубе', 'компания друзей-школьников', 'студент перед сессией',
  'опытный киберкотлет, который «всех знает»', 'папа, пришедший «просто посмотреть»', 'бармен/админ и его «секретный рецепт»'];
const PAINS = ['«ещё одна катка» и время улетело', 'лаг в самый важный момент', 'клатч 1 против 5', 'гость забыл, зачем пришёл — и играет 6 часов', 'мама звонит, а ты в рейтинге',
  'тимейт ушёл в афк', 'спор «кто лучше» решается дуэлью', 'новичок случайно делает легендарный ход', 'энергетик закончился на самом интересном',
  'соседняя клава щёлкает громче всех', 'бонусы на карте и «хватит ещё на час»', 'ночная смена: клуб почти пуст, но он живой'];
const MOODS = ['самоирония', 'азарт', 'неожиданность', 'уютный вайб', 'вау-эффект', 'тёплый юмор', 'драйв', 'лёгкая интрига'];
const LIMITS = ['снять за 15 минут', 'снять одним дублем', 'без лиц — только руки и экраны', 'снимается на один телефон без штатива', 'нужен максимум один гость',
  'без слов, только текст на экране', 'использовать подсветку клуба как главный визуал', 'уложиться в 12–15 секунд'];
const GAMES = ['CS2', 'Dota 2', 'PUBG', 'Valorant', 'Fortnite', 'GTA V / онлайн-шутеры', 'FIFA / EA FC', 'Minecraft', 'без привязки к конкретной игре (про атмосферу клуба)'];

const sd = $getWorkflowStaticData('global');
const history = (sd.titles || []).slice(-30);

const seed = { format: pick(FORMATS), hero: pick(HEROES), pain: pick(PAINS), mood: pick(MOODS), limit: pick(LIMITS), game: pick(GAMES) };
const prompt = `Придумай ОДНУ идею рилса для Instagram.

СЕЙЧАС: ${wd}, ${dateStr}, ${part} (Октябрьский, Башкортостан). Сезон: ${season}.
Ближайшие поводы: ${near.length ? near.join('; ') : 'особых праздников рядом нет — опирайся на сезон и день недели'}.

ОБЯЗАТЕЛЬНЫЕ ИНГРЕДИЕНТЫ ЭТОЙ ИДЕИ (используй их, но сделай естественно):
• Формат: ${seed.format}
• Герой: ${seed.hero}
• Ситуация/боль геймера: ${seed.pain}
• Настроение: ${seed.mood}
• Игра: ${seed.game}
• Ограничение съёмки: ${seed.limit}

НЕ ПОВТОРЯЙ эти идеи, которые уже были (ни названия, ни суть):
${history.length ? history.map(t => '- ' + t).join('\n') : '- (пока ничего)'}`;
return [{ json: { prompt, seed, now: `${wd}, ${dateStr}, ${part}` } }];

// Сохраняем название в историю (последние 30) и режем текст под лимит Telegram
let out = String($input.first().json.output || '').replace(/\*\*/g, '').replace(/^#{1,3}\s*/gm, '').trim();
if (!out) throw new Error('Агент вернул пустую идею');
const m = /Название:\s*(.+)/i.exec(out);
const sd = $getWorkflowStaticData('global');
sd.titles = (sd.titles || []); 
if (m) { sd.titles.push(m[1].trim().slice(0, 120)); sd.titles = sd.titles.slice(-30); }
if (out.length > 3900) out = out.slice(0, 3900);
return [{ json: { text: out } }];
